async function stageEvents(ops){if(!stageOwner)throw Error('LOGIN_REQUIRED');const previous=pending;pending=new Map(previous);for(const op of ops){const old=pending.get(op.eventId);if(!old&&pending.size>=100)throw Error('STAGE_LIMIT');if(old?.action==='create'&&op.action==='delete'){pending.delete(op.eventId);continue;}const action=old?.action==='create'?'create':op.action,expectedVersion=Number(old?.expectedVersion??op.expectedVersion??0),changes=op.changes??old?.changes,unchanged=old&&old.action===action&&old.expectedVersion===expectedVersion&&JSON.stringify(old.changes||{})===JSON.stringify(changes||{});pending.set(op.eventId,{...old,...op,calendarId:old?.calendarId||op.calendarId||state.calendarId,action,baseVersion:Number(old?.baseVersion??op.baseVersion??op.expectedVersion??0),expectedVersion,stageId:unchanged?old.stageId:crypto.randomUUID()});}try{await persistPending();}catch(e){pending=previous;throw e;}}
