async function api(action,payload={},timeoutMs=30000){if(!window.APP_CONFIG.API_URL)throw new Error('API_NOT_CONFIGURED');const controller=timeoutMs?new AbortController():null,timer=controller?setTimeout(()=>controller.abort(),timeoutMs):null;try{const r=await fetch(window.APP_CONFIG.API_URL,{method:'POST',redirect:'follow',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({action,...payload,...(state.calendarId&&action!=='auth'&&action!=='listCalendars'&&action!=='createCalendar'&&!payload.calendarId?{calendarId:state.calendarId}:{}),...(sessionToken?{sessionToken}:{})}),...(controller?{signal:controller.signal}:{})}),data=await r.json();if(!data.ok){if(data.error==='SESSION_EXPIRED'||data.error==='UNAUTHORIZED'){sessionToken='';sessionStorage.removeItem('calendarSession');updateSync();$('#app-content').hidden=true;$('#login-panel').hidden=false;toast('La sesión venció. Ingresá de nuevo.','error');}throw new Error(data.error||'API_ERROR');}return data;}catch(e){if(controller?.signal.aborted)throw new Error('REQUEST_TIMEOUT');throw e;}finally{clearTimeout(timer);}}
async function initializeAfterLogin(month){stageOwner=await ownerKey(state.username);await restorePending();let data;try{data=await api('bootstrap',{from:`${month}-01`,limit:300,...(state.calendarId?{calendarId:state.calendarId}:{})},30000);state.calendars=data.calendars||[];state.calendarId=data.calendarId||state.calendars[0]?.calendarId||'';state.calendarName=data.calendarName||'';state.groups=data.groups||[];}catch(e){if(!['INVALID_ACTION','CALENDAR_ADMIN_REQUIRED','CALENDAR_READ_ONLY'].includes(e.message))throw e;await loadCalendars();if(!state.calendarId)throw new Error('CALENDAR_ACCESS_DENIED');const [events,groups]=await Promise.all([api('list',{from:`${month}-01`,limit:300},30000),api('listGroups')]);data=events;state.groups=groups.groups||[];}state.events=overlayPending(data.records||[],month);state.monthCache[month]={events:state.events,at:Date.now()};renderCalendarOptions();$('#connection').textContent='Conectado';$('#connection').className='connection online';render();renderAdminSummary();loadCalendarAdminData().catch(()=>{});toast('Sesión iniciada','success');}
