document.querySelectorAll('[data-table-sort=events]').forEach(button=>button.addEventListener('click',()=>{button.dataset.direction=currentEventTableSort.key===button.dataset.sortKey&&currentEventTableSort.direction==='asc'?'desc':'asc';button.textContent=button.dataset.direction==='asc'?'A–Z':'Z–A';currentEventTableSort={key:button.dataset.sortKey,direction:button.dataset.direction};for(const b of document.querySelectorAll('[data-table-sort=events]')){b.dataset.direction=b===button?button.dataset.direction:'asc';b.textContent=b===button?(button.dataset.direction==='asc'?'A–Z':'Z–A'):'A–Z';}sortTableRows($('#events-table'),button.dataset.sortKey,button.dataset.direction);}));
