function calendarInviteErrorMessage(code){return ({CALENDAR_ACCESS_ALREADY_EXISTS:'Google ya detectó una regla de acceso existente. Actualizá los accesos de la agenda antes de reintentar.',CALENDAR_PERMISSION_DENIED:'Google rechazó el acceso. Revisá que la cuenta que ejecuta Apps Script pueda administrar los permisos de esta agenda.',CALENDAR_AUTH_REQUIRED:'Apps Script necesita que autorices nuevamente el acceso a Google Calendar.',CALENDAR_NOT_FOUND:'Apps Script no encuentra la agenda de Google asociada. Revisá la agenda activa y las ejecuciones de Apps Script.',CALENDAR_RATE_LIMITED:'Google limitó temporalmente la consulta de permisos. Esperá un poco antes de volver a intentar.',CALENDAR_API_UNAVAILABLE:'La API de Google Calendar no está disponible ahora. No se envió la invitación.',CALENDAR_API_DISABLED:'No está habilitado el servicio avanzado Google Calendar API en Apps Script o en el proyecto de Google Cloud.',INVITATION_REVOKE_FAILED:'Google no pudo quitar el permiso de esta agenda. No se marcó como revocado.',CALENDAR_INVITATION_LOOKUP_FAILED:'No se pudo consultar la lista de permisos de Google; no se envió la invitación. Desplegá Code.gs y appsscript.json, autorizá el permiso calendar.acls.readonly cuando Google lo solicite y revisá las ejecuciones de Apps Script.',INVITATION_FAILED:'Google no pudo crear la invitación. Revisá permisos y ejecuciones de Apps Script; no se reintentó automáticamente.',INTERNAL_ERROR:'Apps Script devolvió un error interno. Revisá las ejecuciones de Apps Script para conocer la causa.'})[code]||code;}
