async function selectCalendar(calendarId){if(!calendarId||calendarId===state.calendarId)return;if(pending.size){toast('Sincronizá los cambios pendientes antes de cambiar de agenda.','error');renderCalendarOptions();return;}state.calendarId=calendarId;const c=activeCalendar();state.calendarName=c.name;state.groups=[];state.events=[];state.monthCache={};renderCalendarOptions();updateRenameControl();try{await load(true);const groups=await api('listGroups');state.groups=groups.groups||[];render();loadCalendarAdminData().catch(()=>{});}catch(e){toast(`No se pudo cambiar de agenda: ${e.message}`,'error');}}
async function load(force=false){const key=`${state.date.getFullYear()}-${String(state.date.getMonth()+1).padStart(2,'0')}`,hit=state.monthCache[key];if(!force&&hit&&Date.now()-hit.at<30000){state.events=hit.events.map(x=>({...x}));for(const op of pending.values()){const i=state.events.findIndex(x=>x.eventId===op.eventId);if(op.action==='delete'){if(i>=0)state.events.splice(i,1);}else{const local={...(i>=0?state.events[i]:{}),...op.changes,eventId:op.eventId,version:op.expectedVersion||0};if(i>=0)state.events[i]=local;else if(String(local.startAt||'').slice(0,7)===key)state.events.push(local);}}render();return;}toast('Cargando eventos…','loading');applyEventTableFilters();try{const data=await api('list',{from:`${key}-01`,limit:300},30000);if(data.calendarName)setCalendarName(data.calendarName);state.events=overlayPending(data.records||[],key);state.monthCache[key]={events:state.events,at:Date.now()};$('#connection').textContent='Conectado';$('#connection').className='connection online';render();toast('Agenda actualizada','success');}catch(e){$('#connection').textContent=e.message==='API_NOT_CONFIGURED'?'Backend pendiente':e.message==='SESSION_EXPIRED'||e.message==='UNAUTHORIZED'?'Sesión vencida':'Sin conexión';$('#connection').className='connection offline';state.events=[];render();toast(e.message==='REQUEST_TIMEOUT'?'El calendario tardó más de 30 segundos en responder. Intentá actualizar.':e.message==='SESSION_EXPIRED'||e.message==='UNAUTHORIZED'?'La sesión venció. Ingresá de nuevo.':e.message==='API_NOT_CONFIGURED'?'Falta configurar el backend del calendario.':e.message==='SHEET_NOT_FOUND'?'Falta la hoja Eventos en la planilla.':e.message==='CONFIG_SHEET_NOT_FOUND'?'Falta la hoja Config en la planilla.':e.message==='CALENDAR_NOT_FOUND'?'El ID configurado no está accesible; revisá Config!B5.':'No se pudo cargar el calendario. Revisá tu conexión e intentá actualizar.','error');} }
$('#prev').onclick=()=>{state.date.setMonth(state.date.getMonth()-1);load();};$('#next').onclick=()=>{state.date.setMonth(state.date.getMonth()+1);load();};$('#today').onclick=()=>{state.date=new Date();load();};$('#refresh').onclick=()=>{closeActionMenu();if(!state.calendarId){toast('Elegí una agenda antes de actualizar.','error');return;}load(true);};$('#new-event').onclick=()=>{closeActionMenu();if(!canEditAgenda())return;const f=$('#event-form');f.reset();f.dataset.id='';$('#event-group').innerHTML=groupOptions('');f.elements.date.value=isoDay(state.date);toggleCustomReminder();fillRecurrence(f,{frequency:'none'});dialog.showModal();};$('#close-dialog').onclick=$('#cancel').onclick=()=>dialog.close();
$('#event-form').addEventListener('submit',async ev=>{ev.preventDefault();if(!canEditAgenda()){toast('No tenés permiso para editar esta agenda.','error');return;}const f=ev.currentTarget, startAt=`${f.elements.date.value}T${f.elements.time.value}:00`;const zonedStart=`${startAt}-03:00`;let reminderMinutes;try{reminderMinutes=readReminder(f,`${f.elements.date.value}T${f.elements.time.value}:00-03:00`);}catch(_){toast('Revisá el recordatorio: elegí una anticipación válida de 5 minutos a 28 días antes del evento.','error');return;}const changes={title:f.elements.title.value.trim(),startAt:zonedStart,endAt:new Date(new Date(zonedStart).getTime()+3600000).toISOString(),location:f.elements.location.value.trim(),description:f.elements.description.value.trim(),groupId:f.elements.groupId.value||'',reminderMinutes,reminderAt:readReminderAt(f),recurrence:readRecurrence(f)};if(changes.recurrence.end==='date'&&changes.recurrence.until< f.elements.date.value){toast('La fecha final debe ser igual o posterior al primer evento.','error');return;}if(changes.recurrence.end==='count'&&changes.recurrence.count<2){toast('La cantidad debe ser al menos 2 eventos.','error');return;}const payload={eventId:f.dataset.id||crypto.randomUUID(),changes},submitButton=f.querySelector('[type="submit"]'),submitLabel=submitButton.textContent;submitButton.disabled=true;submitButton.textContent='Guardando…';toast('Guardando evento…','loading');if(f.dataset.id)payload.expectedVersion=Number(f.dataset.version);try{const existing=state.events.find(x=>x.eventId===payload.eventId),action=f.dataset.id?'update':'create';await stageEvent({action,eventId:payload.eventId,expectedVersion:payload.expectedVersion||0,changes,baseVersion:payload.expectedVersion||0});const saved={record:{...existing,...changes,eventId:payload.eventId,version:existing?.version||0}},index=state.events.findIndex(x=>x.eventId===saved.record.eventId),month=`${state.date.getFullYear()}-${String(state.date.getMonth()+1).padStart(2,'0')}`;if(saved.record.startAt.slice(0,7)===month||saved.record.recurrence&&saved.record.recurrence.frequency!=='none'){if(index<0)state.events.push(saved.record);else state.events[index]=saved.record;}else if(index>=0)state.events.splice(index,1);state.monthCache={};state.monthCache[month]={events:state.events,at:Date.now()};render();dialog.close();if(saved.record.recurrence&&saved.record.recurrence.frequency!=='none')await load(true);toast('Evento preparado en IndexedDB. Tocá Sincronizar para guardarlo en Sheets/Calendar.','success');}catch(e){toast(e.message==='API_NOT_CONFIGURED'?'Falta configurar el backend':`No se pudo guardar: ${e.message}`,'error');}finally{submitButton.disabled=false;submitButton.textContent=submitLabel;}});
document.addEventListener('click',async ev=>{const del=ev.target.closest('[data-delete]'),edit=ev.target.closest('[data-edit]');if(del){if(!canEditAgenda()){toast('No tenés permiso para editar esta agenda.','error');return;}if(!confirm('¿Eliminar este evento?'))return;toast('Preparando baja en IndexedDB…','loading');try{const target=state.events.find(x=>x.eventId===del.dataset.delete);await stageEvent({action:'delete',eventId:del.dataset.delete,expectedVersion:Number(del.dataset.version),baseVersion:Number(del.dataset.version)});state.events=state.events.filter(x=>x.eventId!==del.dataset.delete);const month=`${state.date.getFullYear()}-${String(state.date.getMonth()+1).padStart(2,'0')}`;state.monthCache={};state.monthCache[month]={events:state.events,at:Date.now()};render();if(target&&target.recurrence&&target.recurrence.frequency!=='none')await load(true);toast('Baja preparada en IndexedDB. Tocá Sincronizar para aplicarla.','success');}catch(e){toast('No se pudo eliminar: '+e.message,'error');}}if(edit){if(!canEditAgenda()){toast('No tenés permiso para editar esta agenda.','error');return;}const item=state.events.find(x=>x.eventId===edit.dataset.edit);if(!item)return;const f=$('#event-form');f.reset();f.dataset.id=item.eventId;f.dataset.version=item.version;f.elements.title.value=item.title||'';f.elements.date.value=(item.seriesStartAt||item.startAt||'').slice(0,10);f.elements.time.value=(item.seriesStartAt||item.startAt||'').slice(11,16);f.elements.location.value=item.location||'';f.elements.description.value=item.description||'';$('#event-group').innerHTML=groupOptions(item.groupId||'');fillReminder(f,item.reminderMinutes,item.seriesStartAt||item.startAt,item.reminderAt);fillRecurrence(f,item.recurrence);dialog.showModal();}});
window.addEventListener('online',()=>load(true));window.addEventListener('offline',()=>{ $('#connection').textContent='Sin conexión';$('#connection').className='connection offline'; });
